begin;
do $test$
declare uid uuid:=extensions.gen_random_uuid();sid uuid:=extensions.gen_random_uuid();actor jsonb;email_value text:='delivery@local.invalid';payload jsonb;did uuid;lease uuid;claim jsonb;result jsonb;month_value text:=to_char(clock_timestamp()at time zone 'Asia/Dhaka','YYYY-MM');subject_ids uuid[];last_subject uuid;
begin
 if to_regclass('private.admin_notification_deliveries')is null then raise exception 'Durable notification delivery foundation missing';end if;
 insert into auth.users(id,email,email_confirmed_at)values(uid,email_value,clock_timestamp());
 insert into public.admin_profiles(user_id,admin_code,display_name,is_active,status)values(uid,'JN-ADM-209971','Delivery Fixture',true,'active');
 insert into public.rbac_user_platform_roles(user_id,role_id,scope)select uid,id,'admin'from public.rbac_platform_roles where code='super_admin'and scope='admin';
 insert into auth.sessions(id,user_id,aal,created_at,updated_at)values(sid,uid,'aal1',now(),now());
 update public.security_settings set admin_totp_enforced=false;
 actor:=jsonb_build_object('userId',uid,'sessionId',sid,'roleVersion',(select version from public.rbac_user_claim_versions where user_id=uid),'currentLevel','aal1');
 perform public.own_admin_email_preferences(actor,'{"admin_security_email_opt_in":true,"admin_recommendation_email_opt_in":true}');
 lease:=(public.claim_admin_accountability_job()->>'leaseId')::uuid;
 result:=public.get_admin_notification_batch(lease,month_value,100,500);
 if result->>'enabled'<>'false'then raise exception 'Job email control defaults on';end if;
 perform public.release_admin_accountability_job(lease,false);
 payload:=jsonb_build_object('from','JnUITS <no-reply@jnuits.org.bd>','replyTo','no-reply@jnuits.org.bd','to',email_value,'subject','JnUITS recommendations','html','<p>Review your profile.</p>','text','Review your profile.');
 if public.queue_admin_recommendation_email(uid,month_value,payload,1,array['own-profile'])is not null then raise exception 'Email queued before activation';end if;
 update private.admin_notification_controls set delivery_enabled=true,delivery_cutover=clock_timestamp()-interval '1 second'where singleton;
 lease:=(public.claim_admin_accountability_job()->>'leaseId')::uuid;
 result:=public.get_admin_notification_batch(lease,month_value,100,500);
 if result->>'enabled'<>'true'or jsonb_array_length(result->'subjects')<>1 then raise exception 'Eligible current-month subject batch missing';end if;
 perform public.advance_admin_digest_cursor(lease,month_value,uid,false);
 if jsonb_array_length(public.get_admin_notification_batch(lease,month_value,100,500)->'subjects')<>0 then raise exception 'Digest cursor did not advance';end if;
 perform public.advance_admin_digest_cursor(lease,month_value,uid,true);
 perform public.release_admin_accountability_job(lease,false);
 did:=public.queue_admin_recommendation_email(uid,month_value,payload,1,array['own-profile']);
 if did is null then raise exception 'Eligible optional digest not queued';end if;
 if public.queue_admin_recommendation_email(uid,month_value,payload||'{"subject":"Changed rubric"}',2,array['own-profile'])is distinct from did then raise exception 'Rubric change duplicated monthly email';end if;
 if(select d.payload->>'subject'from private.admin_notification_deliveries d where d.id=did)<>'JnUITS recommendations'then raise exception 'Retry payload mutated';end if;
 if public.queue_admin_recommendation_email(uid,'2000-01',payload,1,array['own-profile'])is not null then raise exception 'Missed-month digest manufactured';end if;
 lease:=(public.claim_admin_accountability_job()->>'leaseId')::uuid;
 claim:=public.claim_admin_notification_delivery(did,lease);
 if claim is null then raise exception 'Atomic delivery claim failed';end if;
 if public.claim_admin_notification_delivery(did,lease)is not null then raise exception 'Concurrent claim duplicated send';end if;
 if not public.validate_admin_notification_delivery(did,(claim->>'claimToken')::uuid,lease)then raise exception 'Current recipient validation failed';end if;
 update public.portal_user_settings set admin_recommendation_email_opt_in=false where user_id=uid;
 if public.validate_admin_notification_delivery(did,(claim->>'claimToken')::uuid,lease)then raise exception 'Opt-out between enqueue and send ignored';end if;
 update public.portal_user_settings set admin_recommendation_email_opt_in=true where user_id=uid;
 -- Lost accepted-response persistence: expired sending is uncertain, never blindly resent after 24h.
 update private.admin_notification_deliveries set lease_until=clock_timestamp()-interval '1 minute',first_attempt_at=clock_timestamp()-interval '25 hours'where id=did;
 if public.claim_admin_notification_delivery(did,lease)is not null then raise exception 'Unknown accepted send retried beyond provider window';end if;
 update private.admin_notification_deliveries set first_attempt_at=clock_timestamp()-interval '1 hour'where id=did;
 claim:=public.claim_admin_notification_delivery(did,lease);
 if claim is null then raise exception 'Safe original-key retry unavailable';end if;
 perform public.finish_admin_notification_delivery(did,(claim->>'claimToken')::uuid,'failed',null,'rate_limited');
 if not(select has_uncertain_outcome from private.admin_notification_deliveries where id=did)then raise exception 'Earlier uncertainty erased by later rejection';end if;
 update private.admin_notification_deliveries set first_attempt_at=clock_timestamp()-interval '25 hours'where id=did;
 if public.claim_admin_notification_delivery(did,lease)is not null then raise exception 'Latched uncertainty bypassed 24h boundary';end if;
 update private.admin_notification_deliveries set first_attempt_at=clock_timestamp()-interval '1 hour'where id=did;
 claim:=public.claim_admin_notification_delivery(did,lease);
 if not public.finish_admin_notification_delivery(did,(claim->>'claimToken')::uuid,'accepted','provider-notification-fixture',null)then raise exception 'Accepted receipt not stored';end if;
 if(select state from private.admin_notification_deliveries where id=did)<>'accepted'then raise exception 'Provider acceptance falsely reported as delivered';end if;
 if public.claim_admin_notification_delivery(did,lease)is not null then raise exception 'Accepted mail resent';end if;
 result:=public.record_admin_notification_webhook_event('fixture-notice-event','provider-notification-fixture','email.delivered',clock_timestamp());
 if not(result->>'tracked')::boolean then raise exception 'Verified delivery webhook unmatched';end if;
 if not(public.record_admin_notification_webhook_event('fixture-notice-event','provider-notification-fixture','email.delivered',clock_timestamp())->>'duplicate')::boolean then raise exception 'Webhook replay duplicated';end if;
 perform public.record_admin_notification_webhook_event('fixture-notice-sent','provider-notification-fixture','email.sent',clock_timestamp());
 if(select state from private.admin_notification_deliveries where id=did)<>'delivered'then raise exception 'Delayed sent event downgraded delivery';end if;
 perform public.record_admin_notification_webhook_event('fixture-notice-complaint','provider-notification-fixture','email.complained',clock_timestamp());
 if(select state from private.admin_notification_deliveries where id=did)<>'suppressed'then raise exception 'Complaint not suppressed';end if;
 if has_function_privilege('authenticated','public.claim_admin_notification_delivery(uuid,uuid)','execute')then raise exception 'Browser can claim delivery';end if;
 select array_agg(extensions.gen_random_uuid())into subject_ids from generate_series(1,101);
 insert into auth.users(id,email,email_confirmed_at)select subject,'digest-'||subject||'@local.invalid',clock_timestamp()from unnest(subject_ids)subject;
 insert into public.admin_profiles(user_id,admin_code,display_name,is_active,status)select subject,'JN-ADM-'||(700000+position),'Digest Fixture',true,'active'from unnest(subject_ids)with ordinality subjects(subject,position);
 insert into public.rbac_user_platform_roles(user_id,role_id,scope)select subject,r.id,'admin'from unnest(subject_ids)subject cross join public.rbac_platform_roles r where r.code='content_admin'and r.scope='admin';
 insert into public.portal_user_settings(user_id,admin_recommendation_email_opt_in)select subject,true from unnest(subject_ids)subject;
 result:=public.get_admin_notification_batch(lease,month_value,1000,500);
 if jsonb_array_length(result->'subjects')<>100 or result->>'digestEnd'<>'false'then raise exception 'Account batch exceeded 100 or lost backlog';end if;
 last_subject:=(result#>>'{subjects,99,userId}')::uuid;
 perform public.advance_admin_digest_cursor(lease,month_value,last_subject,false);
 result:=public.get_admin_notification_batch(lease,month_value,100,500);
 if jsonb_array_length(result->'subjects')<>1 or result->>'digestEnd'<>'true'then raise exception 'Account batch cursor skipped or repeated subjects';end if;
 perform public.release_admin_accountability_job(lease,false);
end $test$;
rollback;
